// Commit-time reads for the direct_feed bootstrap check (direct-feed-bootstrap.mjs holds the verdict). Only raw native answers
// read through the ordinary observation path are used; a failed, clipped or unexpected answer is "unknown", never a fact.
import { parseInventoryCounts } from './inventory-facts.mjs'
import { directFeedBootstrapMessage, directFeedBootstrapVerdict, DIRECT_FEED_BOOTSTRAP_CODE, VERDICT } from './direct-feed-bootstrap.mjs'

export const DIRECT_FEED_BOOTSTRAP_LIMITS = Object.freeze({ recipe_reads: 40, placements: 8, raw_chars: 200000 })

class Unreadable extends Error {}

async function readJson(agent, cache, tool, args) {
  const key = JSON.stringify([tool, args])
  if (cache.has(key)) return cache.get(key)
  let raw
  try { raw = String(await agent.rcon.command(agent.observationToolCommand(tool, args))) }
  catch { raw = '' }
  if (raw.length > DIRECT_FEED_BOOTSTRAP_LIMITS.raw_chars) raw = ''
  let value
  try { value = JSON.parse(raw) }
  catch { value = undefined }
  cache.set(key, { raw, value })
  return cache.get(key)
}

// The recipe closure of one item: its canonical recipe row and every ingredient's, with raw items named. The same rules the
// production task uses (production-task-runtime.mjs factsFor): a natural resource outranks recycling recipes.
async function recipeClosure(agent, cache, item, rows, rawItems, budget) {
  const queue = [item]; const seen = new Set()
  while (queue.length) {
    const next = queue.shift()
    if (seen.has(next)) continue
    seen.add(next)
    if (rows.has(next) || rawItems.has(next)) continue
    if (budget.reads >= DIRECT_FEED_BOOTSTRAP_LIMITS.recipe_reads) throw new Unreadable('recipe_read_limit')
    budget.reads++
    const { value: detail } = await readJson(agent, cache, 'getRecipeDetails', { item_or_recipe: next, requested_count: 1 })
    if (!detail || typeof detail !== 'object') throw new Unreadable('recipe_unreadable')
    if (detail.truncated === true || detail.recipes?.some(row => row?.crafting_machines_truncated === true)) throw new Unreadable('recipe_incomplete')
    const canonical = Array.isArray(detail.recipes) ? detail.recipes.find(row => row?.name === next) : undefined
    if (detail.mined_from?.length || (detail.harvested_from?.length && canonical?.enabled !== true)) { rawItems.add(next); continue }
    if (detail.found === false && detail.code === 'no_recipe') { rawItems.add(next); continue }
    if (detail.found !== true || !Array.isArray(detail.recipes)) throw new Unreadable('recipe_unreadable')
    const row = canonical ?? (detail.recipes.length === 1 ? detail.recipes[0] : undefined)
    if (!row || !Array.isArray(row.ingredients)) throw new Unreadable('recipe_ambiguous')
    rows.set(next, row)
    // A locked recipe is not expanded: it is no way to build the cell now.
    if (row.enabled !== true || row.applicability?.state === 'unavailable') continue
    queue.push(...row.ingredients.map(ingredient => ingredient?.name).filter(name => typeof name === 'string'))
  }
}

// NPC-placed machines that the step does not preserve and that the game still shows under that unit number and prototype
// (`counts`), and the entity names with a recorded placement the facts neither confirm nor refute (`unresolved`): a lookup that
// failed or could not be read, or a placement past the examination cap. Only the mod's own "no such entity" answer, or a
// different entity under that unit number, confirms absence; uncertainty is never absence.
async function placedMachines(agent, cache, names, preserve) {
  const key = agent.activePlanKey?.()
  const placements = key ? agent.memory.authorizationState?.(key)?.world?.npc_placements : undefined
  const counts = {}; const unresolved = new Set()
  if (!Array.isArray(placements)) return { counts, unresolved }
  const recorded = placements.filter(row => names.has(row.entity_name) && !preserve.includes(row.unit_number))
  const cut = Math.max(0, recorded.length - DIRECT_FEED_BOOTSTRAP_LIMITS.placements)
  for (const placement of recorded.slice(0, cut)) unresolved.add(placement.entity_name)
  for (const placement of recorded.slice(cut)) {
    const { value } = await readJson(agent, cache, 'getEntityStatus', { unit_number: placement.unit_number })
    const entity = value?.found === true ? value.entity : undefined
    if (entity?.unit_number === placement.unit_number && entity.name === placement.entity_name) {
      counts[placement.entity_name] = (counts[placement.entity_name] ?? 0) + 1
    }
    else if (value?.found === false && value.error === 'exact_entity_not_found' && value.unit_number === placement.unit_number) continue
    else if (entity?.unit_number === placement.unit_number && typeof entity.name === 'string') continue
    else unresolved.add(placement.entity_name)
  }
  return { counts, unresolved }
}

async function factsFor(agent, cache, resource, preserve) {
  const { value: mining } = await readJson(agent, cache, 'getMiningDetails', { resource_or_item: resource })
  if (mining?.found !== true || mining.truncated === true || !Array.isArray(mining.resources) || mining.resources.length === 0
    || mining.resources.some(row => row?.drills_truncated === true || !Array.isArray(row?.drills))) return undefined
  const drills = [...new Set(mining.resources.flatMap(row => row.drills.map(drill => drill?.name)))]
  if (drills.length === 0 || drills.some(name => typeof name !== 'string')) return undefined
  const { raw: inventoryRaw } = await readJson(agent, cache, 'getInventoryItems', {})
  const counts = parseInventoryCounts(inventoryRaw)
  if (!counts) return undefined
  const inventory = Object.fromEntries(counts)
  const rows = new Map(); const rawItems = new Set([resource]); const budget = { reads: 0 }
  // A recipe closure is needed only for a drill the NPC would have to craft; held ones need no bill.
  for (const drill of drills) {
    if ((inventory[drill] ?? 0) >= 1) continue
    try { await recipeClosure(agent, cache, drill, rows, rawItems, budget) }
    catch (error) { if (!(error instanceof Unreadable)) throw error }
  }
  const smelters = [...rows.values()].filter(row => row.crafting_machines?.length > 0).flatMap(row => row.crafting_machines.map(machine => machine?.name))
  const names = new Set([...drills, ...smelters.filter(name => typeof name === 'string')])
  const { counts: placed, unresolved } = await placedMachines(agent, cache, names, preserve)
  return { drills, recipes: [...rows.values()], raw: [...rawItems], inventory, placed, unresolved: [...unresolved] }
}

/**
 * A refusal ({ code, message, details }) when a direct_feed step of this planner draft cannot bootstrap its cell without the
 * resource it forbids by hand, else undefined. Nothing here changes the plan: the planner corrects its own draft.
 *
 * `firstStep` is the index of the first step of the draft that still has to run (earlier ones are completed history carried by a
 * restage). Only a direct_feed step at that index is judged on today's inventory and placements; any later step follows steps
 * that can change both, so its verdict is unknown until it is about to start. `firstStep: null` means the draft's alignment with
 * a carried prefix is not known: no step can be told apart from completed history, so none is judged.
 */
export async function directFeedBootstrapRefusal(agent, plan, { firstStep = 0 } = {}) {
  const guidance = Array.isArray(plan.executionGuidance) ? plan.executionGuidance : []
  const cache = new Map()
  for (const [index, brief] of guidance.entries()) {
    const supply = brief?.materialSupply
    if (supply?.mode !== 'direct_feed') continue
    if (firstStep === null) {
      await agent.traceEvent('plan.direct_feed_bootstrap_checked', { request_id: agent.traceRequest?.id, step_index: index, resource: supply.resource,
        verdict: VERDICT.UNKNOWN, reason: 'prefix_alignment_unknown', pairs: [] })
      continue
    }
    if (index < firstStep) continue
    const completion = plan.stepCompletions?.[index]
    const preserve = Array.isArray(completion?.obligations?.preserve) ? completion.obligations.preserve : []
    const protect = (completion?.checkpoint?.requirements ?? []).filter(row => row?.kind === 'inventory_count')
    const facts = index > firstStep ? undefined : await factsFor(agent, cache, supply.resource, preserve)
    const verdict = facts ? directFeedBootstrapVerdict({ resource: supply.resource, protect, ...facts })
      : { verdict: VERDICT.UNKNOWN, resource: supply.resource, reason: index > firstStep ? 'prior_steps_change_facts' : 'facts_unreadable', pairs: [] }
    await agent.traceEvent('plan.direct_feed_bootstrap_checked', { request_id: agent.traceRequest?.id, step_index: index, resource: supply.resource,
      verdict: verdict.verdict, ...(verdict.reason ? { reason: verdict.reason } : {}), preserved: preserve,
      ...(verdict.unresolved?.length ? { unresolved: verdict.unresolved } : {}),
      pairs: verdict.pairs.slice(0, 8).map(pair => ({ drill: pair.drill, smelter: pair.smelter, missing: pair.missing, status: pair.status, shortfall: pair.shortfall })) })
    if (verdict.verdict !== VERDICT.INFEASIBLE) continue
    return { code: DIRECT_FEED_BOOTSTRAP_CODE, message: directFeedBootstrapMessage(verdict, { stepNumber: index + 1, inventory: facts.inventory }),
      details: { step_index: index, resource: supply.resource } }
  }
  return undefined
}

direct-feed-bootstrap.mjs.text:
// Commit-time bootstrap feasibility of a planner's direct_feed supply choice (Run BB lane B).
//
// A direct_feed step may not hand-acquire or hand-supply its resource (manualSupplyDrift in role-contracts.mjs). Its cell still
// needs one drill and one smelter. A machine the NPC neither holds nor has placed is crafted from native recipes, and a recipe
// bill that ends in the resource itself (iron plates short, and a plate is only smelted from iron-ore) can never be finished by
// a step that forbids the resource by hand. This module is the pure facts -> verdict half: the loop reads the native facts
// (direct-feed-bootstrap-runtime.mjs) and this decides. Anything ambiguous, locked or unreadable is "unknown", never a refusal.
import { compileQuantities } from './quantity-compiler.mjs'

export const DIRECT_FEED_BOOTSTRAP_CODE = 'direct_feed_bootstrap_infeasible'
export const VERDICT = Object.freeze({ INFEASIBLE: 'infeasible', FEASIBLE: 'feasible', UNKNOWN: 'unknown' })

const PAIR_MESSAGE_LIMIT = 1

/** Recipes the resource is an ingredient of that only a placed machine can run (the resource's smelting recipes). */
export function smeltingRecipes(recipes, resource) {
  return (Array.isArray(recipes) ? recipes : []).filter(recipe => Array.isArray(recipe?.ingredients)
    && recipe.ingredients.some(row => row?.name === resource)
    && recipe.hand_craftable_category !== true
    && Array.isArray(recipe.crafting_machines) && recipe.crafting_machines.length > 0
    && recipe.crafting_machines_truncated !== true)
}

function craftable(recipe) {
  return recipe.enabled === true && recipe.applicability?.state !== 'unavailable'
}

/**
 * @param resource  the direct-feed resource (iron-ore)
 * @param drills    names of every drill the native mining facts list for it (complete list only)
 * @param recipes   raw native recipe rows: the drills' recipes and every ingredient's, one row per item
 * @param raw       items the native facts confirm are raw (mined or harvested, no recipe)
 * @param inventory held counts by item name
 * @param placed    NPC-placed machines the step does not preserve, counted by entity name
 * @param unresolved entity names with a recorded unpreserved placement the facts neither confirm nor refute (a failed lookup, or
 *                  a placement past the examination cap); a pair that needs such a machine is unknown, never infeasible
 * @param protect   the step checkpoint's inventory_count requirements ({ item_name, minimum })
 */
export function directFeedBootstrapVerdict({ resource, drills, recipes, raw = [], inventory: heldInventory = {}, placed = {}, unresolved = [], protect = [] }) {
  const unknown = reason => ({ verdict: VERDICT.UNKNOWN, resource, reason, pairs: [] })
  if (typeof resource !== 'string' || !Array.isArray(drills) || drills.length === 0 || !Array.isArray(recipes)) return unknown('facts_incomplete')
  // The resource is what direct_feed forbids supplying by hand: held units of it fund nothing in the bill or the machine count.
  const heldForbidden = heldInventory[resource] ?? 0
  const inventory = { ...heldInventory, [resource]: 0 }
  const unresolvedEntities = new Set(Array.isArray(unresolved) ? unresolved : [])
  const rawItems = new Set([...raw, resource])
  const smelting = smeltingRecipes(recipes, resource)
  // What the cell is for is not protected from its own machines; any other counted stock is another checkpoint's (as
  // production-task-runtime protectedStock keeps the requirements outside a task's targets).
  const products = new Set(smelting.flatMap(recipe => (recipe.products ?? []).map(row => row?.name)))
  const reserved = {}
  for (const row of Array.isArray(protect) ? protect : []) {
    if (typeof row?.item_name === 'string' && Number.isSafeInteger(row.minimum) && !products.has(row.item_name)) reserved[row.item_name] = Math.max(reserved[row.item_name] ?? 0, row.minimum)
  }
  const held = item => Math.max(0, (inventory[item] ?? 0) - (reserved[item] ?? 0))
  const producerOf = item => recipes.find(recipe => recipe?.products?.some(row => row?.name === item))
  const side = ({ entity, item }) => {
    const count = (item ? held(item) : 0) + (placed[entity] ?? 0)
    if (count >= 1) return { entity, item, available: true, count }
    if (unresolvedEntities.has(entity)) return { entity, item, unknown: true, unresolved: true }
    const recipe = item ? producerOf(item) : undefined
    if (!recipe) return { entity, item, unknown: true }
    return craftable(recipe) ? { entity, item, craft: true } : { entity, item, locked: true }
  }
  // A locked recipe is no way to build the cell now: it neither proves nor disproves the bootstrap.
  const drillSides = [...new Set(drills)].map(name => side({ entity: name, item: name })).filter(row => !row.locked)
  const machines = new Map()
  for (const recipe of smelting) for (const machine of recipe.crafting_machines) {
    if (typeof machine?.name === 'string' && !machines.has(machine.name)) machines.set(machine.name, { entity: machine.name, item: machine.placed_by_item })
  }
  const smelterSides = [...machines.values()].map(side).filter(row => !row.locked)
  // The compiler reads bounded counts of the items the bill can touch, never the whole backpack.
  const touched = new Set(recipes.flatMap(recipe => [...(recipe?.ingredients ?? []), ...(recipe?.products ?? [])].map(row => row?.name)))
  const stock = Object.fromEntries(Object.entries(inventory).filter(([item]) => touched.has(item)).map(([item, count]) => [item, Math.min(count, 10000)]))
  const reservedForBill = Object.fromEntries(Object.entries(reserved).filter(([item]) => touched.has(item)).map(([item, count]) => [item, Math.min(count, 10000)]))
  const billFor = rows => {
    try {
      const bill = compileQuantities({ targets: rows.map(row => ({ item_name: row.item, count: 1 })), recipes, inventory: stock, reserved: reservedForBill })
      return { nodes: bill.nodes, acquisition: bill.acquisition }
    }
    catch { return undefined }
  }
  const pairs = []
  for (const drill of drillSides) for (const smelter of smelterSides.length > 0 ? smelterSides : [undefined]) pairs.push(assess({ drill, smelter }))
  function assess({ drill, smelter }) {
    const base = { drill: drill.entity, ...(smelter ? { smelter: smelter.entity } : {}) }
    const missing = [drill, smelter].filter(row => row && !row.available)
    const names = missing.map(row => row.item ?? row.entity)
    // A machine that may already stand (an unresolved recorded placement) makes the whole pair unknown.
    if (missing.some(row => row.unresolved)) return { ...base, missing: names, status: VERDICT.UNKNOWN }
    // One machine whose own bill ends in the resource fails the pair whatever the other machine is: building both only
    // draws more from the same stock.
    for (const row of missing) {
      if (row.unknown) continue
      const alone = billFor([row])
      const leaf = alone?.acquisition.find(entry => entry.item_name === resource)
      if (leaf) return { ...base, missing: [row.item], status: VERDICT.INFEASIBLE, bill: alone, shortfall: leaf.count }
    }
    if (missing.length === 0) return { ...base, missing: [], status: smelter ? VERDICT.FEASIBLE : VERDICT.UNKNOWN }
    if (missing.some(row => row.unknown)) return { ...base, missing: names, status: VERDICT.UNKNOWN }
    const joint = billFor(missing)
    if (!joint) return { ...base, missing: names, status: VERDICT.UNKNOWN }
    const leaf = joint.acquisition.find(entry => entry.item_name === resource)
    const status = leaf ? VERDICT.INFEASIBLE
      : smelter && joint.acquisition.every(entry => rawItems.has(entry.item_name)) ? VERDICT.FEASIBLE : VERDICT.UNKNOWN
    return { ...base, missing: names, status, bill: joint, ...(leaf ? { shortfall: leaf.count } : {}) }
  }
  const verdict = pairs.length === 0 ? VERDICT.UNKNOWN
    : pairs.every(pair => pair.status === VERDICT.INFEASIBLE) ? VERDICT.INFEASIBLE
      : pairs.some(pair => pair.status === VERDICT.FEASIBLE) ? VERDICT.FEASIBLE : VERDICT.UNKNOWN
  return { verdict, resource, reserved, pairs, ...(heldForbidden > 0 ? { held_forbidden: heldForbidden } : {}), ...(unresolvedEntities.size > 0 ? { unresolved: [...unresolvedEntities] } : {}) }
}

function ingredientText(rows) {
  return rows.map(row => `${row.count} ${row.item_name}`).join(' + ')
}

// A craft bill as facts: each recipe once, its per-craft ingredients, and how many crafts (or smelts) the bill needs.
function billText(nodes) {
  return nodes.map(node => `${node.item_name}${node.crafts > 1 ? ` x${node.crafts}` : ''}${node.hand_craftable ? '' : ' (smelted/machine-made)'} = ${ingredientText(node.ingredients)}`).join('; ')
}

/** The planner-facing refusal text for an infeasible verdict: machine, bill, what is held, the shortfall, what would change it. */
export function directFeedBootstrapMessage(verdict, { stepNumber, inventory = {} } = {}) {
  const infeasible = verdict.pairs.filter(pair => pair.status === VERDICT.INFEASIBLE)
  const distinct = []
  for (const pair of infeasible) {
    const signature = JSON.stringify([pair.missing, pair.bill.nodes.map(node => [node.item_name, node.crafts])])
    if (!distinct.some(row => row.signature === signature)) distinct.push({ signature, pair })
  }
  distinct.sort((a, b) => a.pair.shortfall - b.pair.shortfall)
  const resource = verdict.resource
  const parts = distinct.slice(0, PAIR_MESSAGE_LIMIT).map(({ pair }) => {
    const inputs = [...new Set(pair.bill.nodes.flatMap(node => node.ingredients.map(row => row.item_name)))]
    const heldText = inputs.filter(item => item !== resource).map(item => [item, inventory[item] ?? 0]).filter(([, count]) => count > 0).map(([item, count]) => `${item} ${count}`).join(', ') || 'none of its inputs'
    return `crafting ${pair.missing.join(' + ')} (${billText(pair.bill.nodes)}) from what you hold (${heldText}) still needs ${pair.shortfall} ${resource}`
  })
  const others = distinct.slice(PAIR_MESSAGE_LIMIT).map(({ pair }) => `${pair.missing.join(' + ')} needs ${pair.shortfall} ${resource}`)
  const pairs = infeasible.map(pair => (pair.smelter ? `${pair.drill}/${pair.smelter}` : pair.drill))
  const reserved = Object.entries(verdict.reserved ?? {}).map(([item, count]) => `${item} ${count}`)
  return `${DIRECT_FEED_BOOTSTRAP_CODE}: step ${stepNumber} selects materialSupply direct_feed for ${resource}, which forbids hand-mining or hand-supplying ${resource}, but its cell cannot be built without it. `
    + `Native facts: ${parts.join('; and ')}${others.length ? `; the other candidate bills are larger (${others.join(', ')})` : ''}. `
    + `${verdict.held_forbidden > 0 ? `${resource} ${verdict.held_forbidden} is held, but direct_feed forbids hand-supplying it, so it funds nothing here. ` : ''}`
    + `Every candidate drill/smelter pair that is not already held or placed outside obligations.preserve ends this way (${pairs.join(', ')})`
    + `${reserved.length ? `; stock protected by this step's checkpoint is excluded (${reserved.join(', ')})` : ''}. `
    + `Nothing was committed. Resubmit with materialSupply manual_bootstrap for ${resource} (a finite bootstrap in a separate furnace), or with the missing machine held or funded first.`
}
